static Proto::Frame plan(MainVehicle::Controller& c,uint16_t id,uint8_t a,uint8_t b=255){uint8_t p[15]={};Proto::put32(p,c.state.session);Proto::put32(p+4,c.state.safetyEpoch);p[8]=b==255?1:2;p[9]=a;p[10]=b;Proto::put16(p+9+p[8],500);Proto::Frame q;Proto::make(q,Proto::ACTUATE_BATCH,id,0,p,11+p[8]);return q;}
static void slm(MainVehicle::Controller& c,uint32_t at){Proto::Frame f;Proto::slmMeta(f,c.state.session);assert(c.acceptUART(f,at));}
static void metadata(MainVehicle::Controller& c,uint32_t at){uint8_t p[8]={Proto::ADAS_ROLE,1,20,25,3,Proto::VERSION,70,0};Proto::Frame q,r;Proto::make(q,Proto::HELLO,0);Proto::make(r,Proto::ADAS_META,0,0,p,8);assert(c.acceptADAS(r,q,at));}
static void sensor(MainVehicle::Controller& c,uint32_t at,uint16_t sample,uint16_t range,uint8_t flags){uint8_t p[18]={Proto::ADAS_ROLE,flags};Proto::put16(p+2,range);Proto::put16(p+4,sample);p[8]=20;p[9]=25;p[10]=3;p[11]=3;Proto::put16(p+12,70);Proto::Frame q,r;Proto::make(q,Proto::STATUS,0);Proto::make(r,Proto::ADAS_STATUS_REPLY,0,0,p,18);assert(c.acceptADAS(r,q,at));c.tick(at);}
static void drain(MainVehicle::Controller& c){Proto::Frame q;while(c.periph.pop(q)){}while(c.uart.pop(q)){} }
static void peer(MainVehicle::Controller& c,uint32_t at){assert(c.awaitingPeripheral());Proto::Frame q=c.pendingPeripheral(),r;if(Proto::op(q)==Proto::HELLO)Proto::peripheralMeta(r,c.state.session,Proto::id(q));else if(Proto::op(q)==Proto::SAFETY_POLICY||Proto::op(q)==Proto::STATE_SYNC||Proto::op(q)==Proto::SENSOR_TELEMETRY)Proto::ack(r,q);else {uint8_t p[18]={};Proto::put32(p,c.state.session);Proto::put32(p+4,c.state.safetyEpoch);if(Proto::op(q)==Proto::ACTUATE_BATCH){const auto a=Proto::payload(q);for(uint8_t i=0;i<a[8];i++){if(a[9+i]==3)p[9]=1;if(a[9+i]==8)p[11]=1;}}Proto::put16(p+14,Proto::id(q));Proto::make(r,Proto::op(q)==Proto::STATUS?Proto::STATUS_REPLY:Proto::ACK,Proto::id(q),0,p,18);}assert(c.acceptPeripheral(r,q,at));drain(c);}
